from pathlib import Path
import re


def replace_once(text, pattern, replacement, label, flags=0):
    new, n = re.subn(pattern, replacement, text, count=1, flags=flags)
    if n != 1:
        raise SystemExit(f"Could not patch {label}: matches={n}")
    return new

# Backend: session efficiency must use active ratting time, not wall-clock time.
p = Path("app.py")
s = p.read_text(encoding="utf-8")
s = s.replace(
    'seconds=max(1,(parse_iso(ses["ended_at"])-parse_iso(ses["started_at"])).total_seconds())',
    'seconds=max(1,sum(effective_run_seconds(r) for r in rr))',
    1,
)
p.write_text(s, encoding="utf-8")

# Tracker: visible stopwatch freezes on the exact displayed value while paused.
p = Path("static/tracker.js")
s = p.read_text(encoding="utf-8")
pat = re.compile(r''' if\(timerHandle\)clearInterval\(timerHandle\);\n const start=new Date\(run\.started_at\);.*?\n \$\("#completeBtn"\)\.addEventListener''', re.S)
replacement = ''' if(timerHandle)clearInterval(timerHandle);
 const startMs=new Date(run.started_at).getTime();
 const serverElapsed=()=>{
  const paused=Number(run.paused_seconds||0);
  const end=run.paused_at?new Date(run.paused_at).getTime():Date.now();
  return Math.max(0,Math.floor((end-startMs)/1000-paused));
 };
 let uiElapsed=serverElapsed(),uiAnchor=Date.now(),uiPaused=!!run.is_paused;
 const currentSeconds=()=>uiPaused?uiElapsed:Math.max(0,uiElapsed+Math.floor((Date.now()-uiAnchor)/1000));
 const drawTimer=()=>{const sec=currentSeconds(),timer=$("#timer");if(!timer)return;timer.textContent=[Math.floor(sec/3600),Math.floor(sec%3600/60),sec%60].map(x=>String(x).padStart(2,"0")).join(":");timer.classList.toggle("paused",uiPaused)};
 drawTimer();timerHandle=setInterval(drawTimer,250);
 $("#pauseBtn").addEventListener("click",async()=>{
  const b=$("#pauseBtn"),previous={...run},previousElapsed=uiElapsed,previousAnchor=uiAnchor,wasPaused=uiPaused;
  b.disabled=true;
  if(!wasPaused){
   uiElapsed=currentSeconds();uiPaused=true;uiAnchor=Date.now();
   run={...run,is_paused:true,paused_at:new Date().toISOString()};DATA.active=run;b.textContent="▶ Resume Timer";drawTimer();
  }
  try{
   const r=await fetch(`/api/run/${previous.id}/pause`,{method:"POST"}),j=await r.json();
   if(!r.ok)throw new Error(j.error||"Could not update timer.");
   run=j.run;DATA.active=j.run;
   if(wasPaused){uiPaused=false;uiAnchor=Date.now();}else{uiPaused=true;}
   b.textContent=uiPaused?"▶ Resume Timer":"⏸ Pause Timer";drawTimer();
  }catch(err){
   run=previous;DATA.active=previous;uiElapsed=previousElapsed;uiAnchor=previousAnchor;uiPaused=wasPaused;
   b.textContent=uiPaused?"▶ Resume Timer":"⏸ Pause Timer";drawTimer();alert(err.message||"Could not update timer.");
  }finally{b.disabled=false;}
 });
 $("#completeBtn").addEventListener'''
s, n = pat.subn(replacement, s, count=1)
if n != 1:
    raise SystemExit(f"Could not patch stopwatch: matches={n}")
p.write_text(s, encoding="utf-8")

# React-owned pages: keep analytics and character/history controls inside React.
p = Path("static/react/main.tsx")
s = p.read_text(encoding="utf-8")
s = s.replace(
    'when=(v:any)=>v?String(v).slice(0,16).replace("T"," "):"—"',
    'when=(v:any)=>{if(!v)return"—";const d=new Date(v);return Number.isNaN(d.getTime())?String(v):d.toLocaleString(undefined,{year:"numeric",month:"short",day:"2-digit",hour:"2-digit",minute:"2-digit"})}',
    1,
)

shell_block = '''function EveClock(){const[t,setT]=useState(new Date().toLocaleTimeString("en-GB",{timeZone:"UTC",hour12:false}));useEffect(()=>{const h=setInterval(()=>setT(new Date().toLocaleTimeString("en-GB",{timeZone:"UTC",hour12:false})),1000);return()=>clearInterval(h)},[]);return <div className="eve-time"><span>EVE TIME</span><b data-eve-clock>{t}</b><small>NEW EDEN TIME · UTC</small></div>}
function GlobalActions(){const[esi,setEsi]=useState<any>(null),[busy,setBusy]=useState(false);const load=()=>fetch('/api/dashboard').then(r=>r.ok?r.json():null).then(d=>{if(d)setEsi(d.esi||{})}).catch(()=>{});useEffect(()=>{load()},[]);const sync=async()=>{setBusy(true);try{const r=await fetch('/api/sync',{method:'POST'}),j=await r.json().catch(()=>({}));if(!r.ok||j.ok===false)throw new Error('ESI sync failed');setEsi(j.dashboard?.esi||j.esi||esi);if(!j.dashboard)await load()}catch{await load()}finally{setBusy(false)}};const last=esi?.last_success||esi?.last_sync,status=esi?.configured===false?'ESI not configured':esi?.last_error?'ESI sync issue':last?`Synced ${relative(last)}`:'Not synced yet';return <><div className="global-sync-card"><button className="secondary global-sync-btn" disabled={busy||esi?.configured===false} onClick={sync}>{busy?'Syncing…':'↻ Sync ESI'}</button><span className="muted global-sync-status">{status}</span></div><a className="button top-connect" href="/login">+ Connect Character</a></>}
function Shell({active,title,actions,children}:any){const nav=[["dashboard","⌂","Dashboard","/dashboard"],["tracker","◉","Tracker","/"],["history","◷","History","/history"],["progression","▥","Progression","/progression"],["fits","◈","Fits","/?view=fits"],["characters","♙","Characters","/progression?view=characters"],["settings","⚙","Settings","/?view=settings"]];return <div className={"app-shell page-"+active}><aside className="sidebar"><div className="brand"><div className="brand-mark">EVE</div><span>RATTING TRACKER</span><small>v{BOOT.version||""}</small></div><nav className="side-nav">{nav.map(([id,ic,label,url])=><a key={id} className={active===id?"active":""} href={url}><span>{ic}</span>{label}</a>)}</nav><div className="sidebar-space"><span>NEW EDEN</span><b>ENDLESS POSSIBILITIES</b></div></aside><main className="main-stage"><header className="eve-topbar"><div className="system-head"><h1>W-16DY</h1><span>· Brave Collective · Null Sec</span><small>SAME SPACE. DIFFERENT OPPORTUNITIES.</small><em>{title}</em></div><div className="topbar-right">{active==="tracker"?actions:<GlobalActions/>}<EveClock/></div></header>{children}<footer className="eve-footer">ISK TODAY · FREEDOM TOMORROW</footer></main></div>}'''
s = replace_once(s, r'function EveClock\(\).*?(?=\nfunction loadScript\()', shell_block, 'global shell', re.S)

history_block = '''function HistoryPage(){const h=BOOT.history||{},[runs,setRuns]=useState<any[]>(h.runs||[]),[sessions]=useState<any[]>(h.sessions||[]),[modal,setModal]=useState<any>(null),[q,setQ]=useState("");const filtered=runs.filter((r:any)=>!q||`${r.anomaly} ${r.variant||""} ${r.system_name||""}`.toLowerCase().includes(q.toLowerCase()));const runTotal=Number(h.run_total??runs.length),sessionTotal=Number(h.session_total??sessions.length),avgDur=Math.round(Number(h.summary?.avg_duration_seconds??(runs.length?runs.reduce((a:number,r:any)=>a+money(r.duration_seconds),0)/runs.length:0))/60),totalBonus=Number(h.summary?.total_bonus??runs.reduce((a:number,r:any)=>a+money(r.escalation_sale_value)+money(r.rare_spawn_value),0));const href=(rp:number,sp:number)=>`/history?days=${h.days||7}&run_page=${rp}&session_page=${sp}`;const pages=(cur:number,total:number)=>{const out:number[]=[];for(let i=Math.max(1,cur-2);i<=Math.min(total,cur+2);i++)out.push(i);return out};const Pager=({kind,current,total,other}:any)=><div className="pagination-bar" data-pagination={kind}><a className="button secondary" aria-disabled={current<=1} href={kind==="runs"?href(Math.max(1,current-1),other):href(other,Math.max(1,current-1))}>← Previous</a>{pages(current,total).map((n:number)=><a key={n} className={"button secondary "+(n===current?"selected":"")} href={kind==="runs"?href(n,other):href(other,n)}>{n}</a>)}<span className="page-label">Page {current} of {total}</span><a className="button secondary" aria-disabled={current>=total} href={kind==="runs"?href(Math.min(total,current+1),other):href(other,Math.min(total,current+1))}>Next →</a></div>;const delRun=async(id:number)=>{if(!confirm("Delete this run? This cannot be undone."))return;const r=await fetch(`/api/run/${id}`,{method:"DELETE"});if(r.ok)location.reload()};const delSession=async(id:number)=>{if(!confirm("Delete this entire session and all of its runs? This cannot be undone."))return;const r=await fetch(`/api/session/${id}`,{method:"DELETE"});if(r.ok)location.reload()};const recentEsc=h.recent_escalations||runs.filter((r:any)=>r.escalation_name).slice(0,8);return <Shell active="history" title="SESSION & SITE HISTORY"><section className="metric-grid history-metrics"><article className="metric-card"><span>Total Recorded Runs</span><b>{runTotal}</b><small>All completed sites</small></article><article className="metric-card"><span>Total Sessions</span><b>{sessionTotal}</b><small>All completed sessions</small></article><article className="metric-card"><span>Avg Site Duration</span><b>{avgDur}m</b><small>Completed sites</small></article><article className="metric-card"><span>Total Bonuses</span><b>{dynamicIsk(totalBonus)}</b><small>Escalations + rare drops</small></article></section><section className="panel sci-panel history-main"><div className="panel-head"><div><h2>Session & Site History</h2><span className="muted">Browse every recorded site. Analytics period does not limit these pages.</span></div><span className="history-page-count">{runTotal} runs</span></div><div className="history-filterbar"><input placeholder="Filter this page by anomaly, variant or system" value={q} onChange={e=>setQ(e.target.value)}/><a className={"button secondary "+(h.days===7?"selected":"")} href="/history?days=7">7 days</a><a className={"button secondary "+(h.days===30?"selected":"")} href="/history?days=30">30 days</a></div><div className="table-wrap"><table><thead><tr><th>Date</th><th>System</th><th>Anomaly</th><th>Variant</th><th>Time</th><th>Bounty</th><th>ISK/hr</th><th>Bonus</th><th>Outcome</th><th></th></tr></thead><tbody>{filtered.map((r:any)=><tr key={r.id} id={`runRow${r.id}`}><td>{when(r.ended_at)}</td><td>{r.system_name||"—"}</td><td><b>{r.anomaly}</b></td><td>{r.variant||"—"}</td><td>{r.duration_label}</td><td>{iskM(r.combined_bounty)}</td><td>{iskM(r.isk_hr)}</td><td>{r.escalation_status?`${r.escalation_status} · `:""}{r.escalation_sale_value?`${iskM(r.escalation_sale_value)} ISK`:money(r.rare_spawn_value)?`${dynamicIsk(r.rare_spawn_value)} ISK`:"—"}</td><td><span className="status-pill good-pill">Completed</span></td><td><div className="inline"><button className="tiny" onClick={async()=>{const x=await fetch(`/api/run/${r.id}`).then(z=>z.json());setModal({type:"run",data:x.run,escalations:x.escalations})}}>Edit</button><button className="danger tiny" onClick={()=>delRun(r.id)}>Delete</button></div></td></tr>)}</tbody></table></div><Pager kind="runs" current={Number(h.run_page||1)} total={Number(h.run_pages||1)} other={Number(h.session_page||1)}/></section><section className="panel sci-panel session-history-panel"><div className="panel-head"><div><h2>Session History</h2><span className="muted">Session totals including loot and salvage.</span></div><span className="history-page-count">{sessionTotal} sessions</span></div><div className="table-wrap"><table><thead><tr><th>Session</th><th>System(s)</th><th>Sites</th><th>Duration</th><th>Bounty</th><th>Loot</th><th>Salvage</th><th>Bonus</th><th>Total</th><th></th></tr></thead><tbody>{sessions.map((ss:any)=><tr key={ss.id} id={`sessionRow${ss.id}`}><td>#{ss.id}</td><td>{ss.systems||"—"}</td><td>{ss.site_count}</td><td>{ss.duration_label}</td><td>{iskM(ss.bounty)}</td><td>{iskM(ss.loot_value)}</td><td>{iskM(ss.salvage_value)}</td><td>{iskM(ss.bonus)}</td><td><b className="green-text">{iskM(ss.total)}</b></td><td><div className="inline"><button className="tiny" onClick={()=>setModal({type:"session",data:{...ss}})}>Edit</button><button className="danger tiny" onClick={()=>delSession(ss.id)}>Delete</button></div></td></tr>)}</tbody></table></div><Pager kind="sessions" current={Number(h.session_page||1)} total={Number(h.session_pages||1)} other={Number(h.run_page||1)}/></section><div className="history-lower"><section className="panel sci-panel"><div className="panel-head"><h2>ESS Payment History</h2></div><div className="table-wrap"><table><thead><tr><th>Date</th><th>Amount</th><th>Character</th></tr></thead><tbody>{(h.ess||[]).slice(0,8).map((e:any,i:number)=><tr key={`${e.character_id}-${e.entry_id}-${i}`}><td>{when(e.date)}</td><td><b className="green-text">{iskM(e.amount)}</b></td><td>{e.character_name}</td></tr>)}</tbody></table></div></section><section className="panel sci-panel"><div className="panel-head"><h2>Recent Escalations</h2></div><div className="escalation-list">{recentEsc.map((r:any)=><div key={r.id}><i></i><span>{when(r.ended_at)}</span><span>{r.system_name||"—"}</span><b>{r.escalation_name}</b><small>{r.escalation_status||"Pending"}</small><strong className="recent-escalation-value">{["Sold","Ran Myself"].includes(r.escalation_status)&&money(r.escalation_sale_value)?`${dynamicIsk(r.escalation_sale_value)} ISK`:"—"}</strong></div>)}{!recentEsc.length&&<div className="empty">No escalations recorded.</div>}</div></section></div>{modal?.type==="run"&&<RunEditModal state={modal} onClose={()=>setModal(null)}/>} {modal?.type==="session"&&<SessionEditModal state={modal} onClose={()=>setModal(null)}/>}</Shell>}'''
s = replace_once(s, r'function HistoryPage\(\).*?(?=\nfunction RunEditModal\()', history_block, 'HistoryPage', re.S)

characters_block = '''function CharactersPage(){const base=BOOT.characters||[],[dash,setDash]=useState<any>(null);useEffect(()=>{fetch('/api/dashboard').then(r=>r.ok?r.json():null).then(setDash).catch(()=>{})},[]);const live=dash?.characters||[],esi=dash?.esi||{};const chars=base.map((c:any)=>({...c,...(live.find((x:any)=>x.id===c.id)||{})}));const esiState=esi.configured===false?"Not configured":esi.last_error?"Issue":"Online",esiGood=esiState==="Online";const removeCharacter=async(c:any)=>{if(!confirm(`Remove ${c.name} from this tracker? Historical runs, sessions, ESS and statistics will be kept.`))return;const r=await fetch(`/api/character/${c.id}`,{method:'DELETE'}),j=await r.json().catch(()=>({}));if(!r.ok){alert(j.error||'Could not remove character.');return}location.reload()};return <Shell active="characters" title="CONNECTED CHARACTERS"><section className="metric-grid character-metrics"><article className="metric-card"><span>Connected Characters</span><b>{chars.length}</b><small>Available to the tracker</small></article><article className="metric-card"><span>Main Character</span><b>{chars.filter((c:any)=>c.role==="main").length}</b><small>Primary ratting character</small></article><article className="metric-card"><span>Alts</span><b>{chars.filter((c:any)=>c.role!=="main").length}</b><small>Additional participants</small></article><article className="metric-card"><span>ESI Status</span><b className={esiGood?"green-text":"amber-text"}>{esiState}</b><small>{esi.last_success?`Last sync ${relative(esi.last_success)}`:"Waiting for sync state"}</small></article></section><div className="characters-layout"><section className="panel sci-panel"><div className="panel-head"><div><h2>Connected Characters</h2><span className="muted">Manage EVE Online characters and inspect their training queue.</span></div></div><div className="character-stack">{chars.map((c:any)=><article className="character-card-xl" key={c.id}><img src={c.portrait} alt=""/><div className="character-main"><div className="character-title"><h2>{c.name}</h2><span className={c.role==="main"?"role-chip main":"role-chip"}>{c.role==="main"?"Main":"Alt"}</span></div><span className="online-label"><i></i> Connected</span><div className="character-facts"><div><small>Total SP</small><b>{Number(c.total_sp||0).toLocaleString("en-US")}</b></div><div><small>Last Snapshot</small><b>{c.captured_at?when(c.captured_at):"Waiting for ESI"}</b></div><div><small>Queue</small><b>{c.queue?.length||0} skills</b></div></div></div><div className="character-actions"><a className="button secondary" href={`/progression?view=characters#char-${c.id}`}>View Details</a><button className="danger remove-character" onClick={()=>removeCharacter(c)}>Remove Character</button></div></article>)}</div></section><section className="panel sci-panel sync-status"><h2>Character Sync Status</h2>{[["ESI Connection",esi.configured===false?"Not configured":esi.last_error?"Issue":"Available"],["Character Data",esi.last_error?"Needs attention":"Available"],["Wallet & ISK",esi.last_error?"Needs attention":"Available"],["Bounty History",esi.last_error?"Needs attention":"Available"],["Skills & Queue",esi.last_error?"Needs attention":"Available"],["Location & Activity",esi.last_error?"Needs attention":"Available"]].map(([x,status])=><div className="sync-row" key={x}><i>{status==="Available"?"✓":"!"}</i><span>{x}</span><b className={status==="Available"?"green-text":"amber-text"}>{status}</b></div>)}</section></div></Shell>}'''
s = replace_once(s, r'function CharactersPage\(\).*?(?=\nfunction ProgressionPage\()', characters_block, 'CharactersPage', re.S)

progression_block = '''function ProgressionPage(){const[dash,setDash]=useState<any>(null);useEffect(()=>{fetch('/api/dashboard').then(r=>r.ok?r.json():null).then(setDash).catch(()=>{})},[]);const recent=dash?.recent||[],site=BOOT.site_performance||[],luck=BOOT.luck_stats||{},escLuck=luck.escalations||{},rareLuck=luck.rare_spawns||{},breakdown=rareLuck.breakdown||{Commander:0,Dreadnought:0,Titan:0,Other:0},rareTotal=Math.max(1,Number(rareLuck.total||0)),days=Number(luck.days||30);const duration=(s:any)=>{const n=Math.max(0,Number(s||0));return n>=3600?`${Math.floor(n/3600)}h ${Math.round(n%3600/60)}m`:`${Math.round(n/60)}m`};const milestones:any[]=[];if(recent.length)milestones.push(["★","Recent activity",`${recent.length} recent site${recent.length===1?"":"s"} tracked`]);const pb=recent.reduce((best:any,r:any)=>!best||money(r.isk_hr)>money(best.isk_hr)?r:best,null);if(pb&&money(pb.isk_hr)>0)milestones.push(["🏆","Recent Personal Best",`${dynamicIsk(pb.isk_hr)}/h`]);const esc=recent.find((r:any)=>r.escalation_name);if(esc)milestones.push(["◇","Escalation Logged",esc.escalation_name]);const rare=recent.find((r:any)=>r.rare_spawn_type);if(rare)milestones.push(["✦","Rare Spawn",rare.rare_spawn_type]);return <Shell active="progression" title="RATTING PROGRESSION"><section className="metric-grid progression-metrics"><article className="metric-card"><span>Avg ISK/h Trend</span><b>{dash?dynamicIsk(dash.stats?.avg_isk_hr):"—"}</b><small>Current tracked average</small></article><article className="metric-card"><span>Sites Today</span><b>{dash?.stats?.today_sites||0}</b><small>Completed today</small></article><article className="metric-card"><span>Today's Bounty</span><b>{dynamicIsk(dash?.stats?.today_isk)}</b><small>All connected participants</small></article><article className="metric-card"><span>Today's ESS</span><b>{dynamicIsk(dash?.stats?.today_ess)}</b><small>Wallet ESS payments</small></article></section><section id="sitePerformanceV3" className="panel sci-panel site-performance-v3"><div className="panel-head"><div><h2>Site Performance</h2><span className="muted">Efficiency by anomaly type for the selected period.</span></div><div className="progression-periods"><a className={"button secondary "+(days===7?"selected":"")} href="/progression?days=7">7 days</a><a className={"button secondary "+(days===30?"selected":"")} href="/progression?days=30">30 days</a></div></div><div className="site-performance-grid">{site.map((g:any)=><article className="site-performance-card" key={g.name}><h3>{g.name}</h3><div className="site-performance-stats"><div><span>Avg ISK / site</span><b>{dynamicIsk(g.avg_isk)} ISK</b></div><div><span>Avg duration</span><b>{duration(g.avg_duration)}</b></div><div><span>Avg ISK / h</span><b>{dynamicIsk(g.avg_isk_hr)} ISK/h</b></div><div><span>Runs</span><b>{g.runs}</b></div></div><div className="best-run">Best run <b>{dynamicIsk(g.best_run)} ISK</b></div></article>)}{!site.length&&<div className="empty">Complete sites to populate performance.</div>}</div></section><section className="panel sci-panel luck-section"><div className="panel-head"><div><h2>Escalations & Rare Spawns</h2><span className="muted">Performance/luck statistics · {days}-day period.</span></div></div><div className="luck-grid"><article className="luck-card"><h3>◇ Escalations</h3><div className="luck-stat-grid"><div className="luck-stat"><span>Total dropped</span><b>{Number(escLuck.total||0)}</b></div><div className="luck-stat"><span>Drop rate / site</span><b>{Number(escLuck.rate||0).toFixed(1)}%</b></div><div className="luck-stat"><span>Most common</span><b>{escLuck.most_common||"—"}</b></div></div></article><article className="luck-card"><h3>✦ Rare Spawns</h3><div className="luck-stat-grid"><div className="luck-stat"><span>Total rare spawns</span><b>{Number(rareLuck.total||0)}</b></div><div className="luck-stat"><span>Spawn rate / site</span><b>{Number(rareLuck.rate||0).toFixed(1)}%</b></div><div className="luck-stat"><span>Total rare loot</span><b>{dynamicIsk(rareLuck.loot_value)} ISK</b></div></div><div className="rare-breakdown">{["Commander","Dreadnought","Titan","Other"].map(k=><div className="rare-breakdown-row" key={k}><span>{k}</span><div><i style={{width:`${Number(breakdown[k]||0)/rareTotal*100}%`}}></i></div><b>{Number(breakdown[k]||0)}</b></div>)}</div></article></div></section><section className="panel sci-panel"><div className="panel-head"><div><h2>Recent Milestones</h2><span className="muted">Automatically derived from your real tracker activity.</span></div></div><div className="milestone-grid">{milestones.slice(0,5).map((m:any,i:number)=><article key={i}><i>{m[0]}</i><div><b>{m[1]}</b><span>{m[2]}</span></div></article>)}{!milestones.length&&<div className="empty">Your first milestone will appear as the tracker collects activity.</div>}</div></section></Shell>}'''
s = replace_once(s, r'function ProgressionPage\(\).*?(?=\nfunction SettingsPage\()', progression_block, 'ProgressionPage', re.S)
s = s.replace('<div className="setting-row"><span>Export</span><b>Available from History</b></div>', '', 1)
p.write_text(s, encoding="utf-8")

# Existing compatibility layer must no longer own Progression rendering.
p = Path("static/prod_update_v3.js")
s = p.read_text(encoding="utf-8")
s = replace_once(s, r'function progression\(\)\{.*?\}(?=\nfunction triggers\()', 'function progression(){return}', 'legacy progression no-op', re.S)
p.write_text(s, encoding="utf-8")
